    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public {
        require(amount <= c.balanceOf(address(this)));
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.burn(amount); if (__ESBMC_reverted()) return;
        assert(c.totalSupply() == supplyBefore - amount);
    }
    receive() external payable {}
