import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount <= c.balanceOf(address(this)));
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        try c.burn(amount) {} catch { return; }
        assertTrue(c.totalSupply() == supplyBefore - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
